import java.awt.*;import java.awt.font.*;import java.awt.geom.*;import java.util.Locale;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import java.io.File; public class IconGlyph {public static void main(String[] args)throws Exception{Font f=new Font("UD Digi Kyokasho N-R",Font.PLAIN,1000);if(!f.canDisplay(0x3042))throw new IllegalStateException("Font lacks hiragana A");GlyphVector glyph=f.createGlyphVector(new FontRenderContext(null,true,true),"\u3042");if(glyph.getNumGlyphs()!=1||glyph.getGlyphCode(0)==f.getMissingGlyphCode())throw new IllegalStateException("Missing glyph");Shape shape=glyph.getOutline();Rectangle2D b=shape.getBounds2D();double scale=50/Math.max(b.getWidth(),b.getHeight());AffineTransform t=new AffineTransform();t.translate(54-b.getCenterX()*scale,54-b.getCenterY()*scale);t.scale(scale,scale);Shape transformed=t.createTransformedShape(shape);BufferedImage image=new BufferedImage(432,432,BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.scale(4,4);g.setColor(new Color(0xFAF6EF));g.fillRoundRect(0,0,108,108,24,24);g.setColor(new Color(0xB0452C));g.fill(transformed);g.dispose();if(args.length>0)ImageIO.write(image,"png",new File(args[0]));PathIterator it=transformed.getPathIterator(null);double[] p=new double[6];StringBuilder s=new StringBuilder();while(!it.isDone()){int k=it.currentSegment(p);String cmd=k==0?"M":k==1?"L":k==2?"Q":k==3?"C":"Z";s.append(cmd);int n=k==0||k==1?2:k==2?4:k==3?6:0;for(int i=0;i<n;i++)s.append(String.format(Locale.US,"%.3f",p[i])).append(i+1==n?" ":",");it.next();}System.out.print(s);}}